import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../App.css";

const RateUser = () => {
  const [usersToRate, setUsersToRate] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const userId = sessionStorage.getItem("userId");
    if (userId) {
      fetch(`${API_BASE_URL}/api/ratings/partners/${userId}`)
        .then((res) => res.json())
        .then((data) => {
          // Make sure it's an array
          if (Array.isArray(data)) {
            setUsersToRate(data);
          } else {
            console.warn("Unexpected response:", data);
            setUsersToRate([]);
          }
          setLoading(false);
        })
        .catch((err) => {
          console.error("Failed to load users to rate:", err);
          setUsersToRate([]);
          setLoading(false);
        });
    }
  }, []);

  const handleRate = async (ratedUserId, rating) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/ratings`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          rater_id: sessionStorage.getItem("userId"),
          rated_id: ratedUserId,
          rating,
        }),
      });

      if (res.ok) {
        alert("Rating submitted!");
        setUsersToRate((prev) => prev.filter((u) => u.id !== ratedUserId));
      } else {
        alert("Failed to submit rating.");
      }
    } catch (err) {
      console.error("Rating error:", err);
      alert("Error submitting rating.");
    }
  };

  return (
    <div>
      <Navbar />
      <main className="rate-user-wrapper">
        <h2>Rate Other Users</h2>

        {loading ? (
          <p>Loading...</p>
        ) : usersToRate.length === 0 ? (
          <p>No users to rate yet.</p>
        ) : (
          usersToRate.map((user) => (
            <div className="rate-card" key={user.id}>
              <h4>{user.username}</h4>
              <p>{user.email}</p>
              {user.average_rating && (
                <p>⭐ Avg Rating: {user.average_rating}</p>
              )}
              <div className="rating-buttons">
                {[1, 2, 3, 4, 5].map((n) => (
                  <button key={n} onClick={() => handleRate(user.id, n)}>
                    {n}⭐
                  </button>
                ))}
              </div>
            </div>
          ))
        )}
      </main>
      <Footer />
    </div>
  );
};

export default RateUser;
